   "code": "// A tiny LSM-tree to see the moving parts: memtable, flush, sorted runs, newest-wins reads\nclass TinyLSM {\n  constructor(limit = 3) { this.mem = new Map(); this.runs = []; this.limit = limit; }\n  put(k, v) { this.mem.set(k, v); if (this.mem.size >= this.limit) this.flush(); }\n  del(k) { this.put(k, null); }                         // a tombstone\n  flush() { this.runs.unshift([...this.mem].sort()); this.mem = new Map(); }\n  get(k) {\n    if (this.mem.has(k)) return this.mem.get(k);\n    for (const run of this.runs) { const hit = run.find(([key]) => key === k); if (hit) return hit[1]; }\n    return undefined;\n  }\n  compact() { // merge all runs, newest wins, drop tombstones\n    const merged = new Map();\n    for (const run of [...this.runs].reverse()) for (const [k, v] of run) merged.set(k, v);\n    this.runs = [[...merged].filter(([, v]) => v !== null).sort()];\n  }\n}\nconst db = new TinyLSM();\n['a', 'b', 'c', 'd'].forEach((k, i) => db.put(k, i));\ndb.put('a', 'new'); db.del('b'); db.put('e', 5);\nconsole.log(db.get('a'), db.get('b'), db.runs.length + ' runs'); // new null 2 runs\ndb.compact();\nconsole.log(db.runs.length + ' run', JSON.stringify(db.runs[0]));",
